package app.veyra;
import android.app.Activity;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.recyclerview.widget.*;import org.json.*;import java.util.*;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public final class DownloadsActivity extends Activity {
 private final PosterLoader posters=new PosterLoader();private final List<JSONObject> shown=new ArrayList<>();private DownloadCards adapter;private TextView summary,empty;private Button ready,transfers;private String filter="ready",snapshot="";private final Handler handler=new Handler(Looper.getMainLooper());
 private final Runnable update=new Runnable(){public void run(){render();handler.postDelayed(this,1500);}};
 public void onCreate(Bundle saved){super.onCreate(saved);Ui.configure(this);if(saved!=null)filter=saved.getString("filter","ready");LinearLayout root=Ui.column(this);LinearLayout top=new LinearLayout(this);Button back=Ui.quiet(this,"‹");back.setContentDescription("Back");back.setOnClickListener(v->finish());top.addView(back);TextView kicker=Ui.text(this,"YOUR OFFLINE COLLECTION",11,Ui.ACCENT);kicker.setLetterSpacing(.15f);top.addView(kicker);root.addView(top);
 TextView title=Ui.text(this,"Go anywhere.",34,Ui.INK);title.setTypeface(null,android.graphics.Typeface.BOLD);root.addView(title);root.addView(Ui.text(this,"Your stories. No connection needed.",14,Ui.MUTED));
 summary=Ui.text(this,"",13,Ui.MUTED);summary.setPadding(0,Ui.dp(this,16),0,Ui.dp(this,16));root.addView(summary);LinearLayout tabs=new LinearLayout(this);ready=Ui.chip(this,"Ready to watch");transfers=Ui.chip(this,"Transfers");tabs.addView(ready,new LinearLayout.LayoutParams(0,Ui.dp(this,48),1));tabs.addView(transfers,new LinearLayout.LayoutParams(0,Ui.dp(this,48),1));root.addView(tabs);ready.setOnClickListener(v->{filter="ready";snapshot="";render();});transfers.setOnClickListener(v->{filter="transfers";snapshot="";render();});
 FrameLayout area=new FrameLayout(this);RecyclerView list=new RecyclerView(this);list.setLayoutManager(new GridLayoutManager(this,getResources().getConfiguration().screenWidthDp>=720?2:1));list.setItemAnimator(null);adapter=new DownloadCards();list.setAdapter(adapter);area.addView(list);empty=Ui.text(this,"",18,Ui.MUTED);empty.setGravity(Gravity.CENTER);empty.setPadding(Ui.dp(this,24),Ui.dp(this,32),Ui.dp(this,24),0);area.addView(empty,new FrameLayout.LayoutParams(-1,-2));root.addView(area,new LinearLayout.LayoutParams(-1,0,1));
 Button about=Ui.quiet(this,"Storage & download help");about.setOnClickListener(v->ActionSheet.show(this,"Downloads",new String[]{"Queue up to 50 transfers · one downloads at a time","Keep at least 256 MB of storage free","Pause, resume, retry and reorder from transfer actions","Downloads stay on this device"},i->{}));root.addView(about);
 if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){Button notifications=Ui.quiet(this,"Enable progress notifications");notifications.setOnClickListener(v->requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},81));root.addView(notifications);}
 setContentView(root);Ui.insets(this,root,20);if((DownloadWorker.active()||getIntent().getBooleanExtra("showTransfers",false))&&saved==null)filter="transfers";
 }
 private static String bytes(long value){return String.format(Locale.US,value>=1073741824L?"%.1f GB":"%.0f MB",value/(value>=1073741824L?1073741824.0:1048576.0));}
 private void render(){List<JSONObject> records=DownloadQueue.ordered(this);String next=records.toString()+DownloadWorker.active()+filter;if(next.equals(snapshot))return;snapshot=next;List<JSONObject> before=new ArrayList<>(shown);long total=0;int count=0;shown.clear();for(JSONObject record:records){try{record.put("_active",DownloadWorker.isActive(record.optString("downloadId")));}catch(JSONException ignored){}total+=record.optLong("bytes");boolean complete=record.optString("state").equals("complete");if(complete)count++;if(complete==filter.equals("ready"))shown.add(record);}summary.setText(count+" ready  ·  "+bytes(total)+" saved  ·  "+bytes(getFilesDir().getUsableSpace())+" free");ready.setSelected(filter.equals("ready"));transfers.setSelected(filter.equals("transfers"));empty.setText(filter.equals("ready")?"Make room for your next escape.\n\nDownload a movie or episode from its title page. It will appear here when ready.":"Nothing downloading right now.\n\nYour active and interrupted transfers appear here.");empty.setVisibility(shown.isEmpty()?View.VISIBLE:View.GONE);DiffUtil.calculateDiff(new DiffUtil.Callback(){public int getOldListSize(){return before.size();}public int getNewListSize(){return shown.size();}public boolean areItemsTheSame(int oldPosition,int newPosition){return before.get(oldPosition).optString("downloadId").equals(shown.get(newPosition).optString("downloadId"));}public boolean areContentsTheSame(int oldPosition,int newPosition){return before.get(oldPosition).toString().equals(shown.get(newPosition).toString());}}).dispatchUpdatesTo(adapter);}
  private void actions(JSONObject record){String id=record.optString("downloadId"),state=record.optString("state");boolean active=DownloadWorker.isActive(id),complete=state.equals("complete");java.util.List<String> labels=new ArrayList<>();java.util.List<Runnable> actions=new ArrayList<>();if(complete){labels.add("Check offline readiness");actions.add(()->{Toast.makeText(this,"Checking saved resources…",Toast.LENGTH_SHORT).show();new Thread(()->{try{TravelCheck.verify(this,id);runOnUiThread(()->Toast.makeText(this,"Saved resources are present. Try playback in airplane mode before travel.",Toast.LENGTH_LONG).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Saved resources are missing or unreadable. Download this title again.",Toast.LENGTH_LONG).show());}},"offline-readiness").start();});}else{if(active||state.equals("queued")){labels.add("Pause");actions.add(()->DownloadWorker.control(this,id,"pause"));}else if(record.has("contentId")){labels.add(state.equals("failed")?"Retry":"Resume");actions.add(()->DownloadWorker.resume(this,id));}if(!active){labels.add("Move earlier");actions.add(()->DownloadQueue.move(this,id,-1));labels.add("Move later");actions.add(()->DownloadQueue.move(this,id,1));}if(active){labels.add("Cancel and discard partial data");actions.add(()->DownloadWorker.control(this,id,"cancel"));}}if(!active){labels.add("Delete offline copy");actions.add(()->new Thread(()->{try{OfflineStore.remove(this,id);runOnUiThread(()->{snapshot="";render();});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Close offline playback before deleting",Toast.LENGTH_LONG).show());}},"download-delete").start());}labels.add("Keep");actions.add(()->{});ActionSheet.show(this,record.optString("title"),labels.toArray(new String[0]),index->{actions.get(index).run();snapshot="";render();});}
 private void resumeQueue(){if(DownloadWorker.active())return;DownloadQueue.recover(this);if(DownloadQueue.next(this)!=null)DownloadWorker.kick(this);}
 private class Card extends RecyclerView.ViewHolder {ImageView art;TextView title,state;ProgressBar progress;Button play,more;Card(View item){super(item);}}
 private class DownloadCards extends RecyclerView.Adapter<Card>{public int getItemCount(){return shown.size();}public Card onCreateViewHolder(ViewGroup parent,int type){LinearLayout card=Ui.card(DownloadsActivity.this);card.setOrientation(LinearLayout.HORIZONTAL);card.setGravity(Gravity.CENTER_VERTICAL);RecyclerView.LayoutParams lp=new RecyclerView.LayoutParams(-1,-2);lp.setMargins(0,Ui.dp(DownloadsActivity.this,12),Ui.dp(DownloadsActivity.this,6),0);card.setLayoutParams(lp);Card h=new Card(card);h.art=new ImageView(DownloadsActivity.this);h.art.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(h.art,new LinearLayout.LayoutParams(Ui.dp(DownloadsActivity.this,82),Ui.dp(DownloadsActivity.this,123)));LinearLayout copy=Ui.column(DownloadsActivity.this);copy.setBackgroundColor(android.graphics.Color.TRANSPARENT);copy.setPadding(Ui.dp(DownloadsActivity.this,14),0,0,0);h.title=Ui.text(DownloadsActivity.this,"",17,Ui.INK);h.title.setMaxLines(2);h.title.setEllipsize(android.text.TextUtils.TruncateAt.END);copy.addView(h.title);h.state=Ui.text(DownloadsActivity.this,"",12,Ui.MUTED);copy.addView(h.state);h.progress=new ProgressBar(DownloadsActivity.this,null,android.R.attr.progressBarStyleHorizontal);h.progress.setProgressTintList(android.content.res.ColorStateList.valueOf(Ui.ACCENT));copy.addView(h.progress,new LinearLayout.LayoutParams(-1,Ui.dp(DownloadsActivity.this,5)));LinearLayout actions=new LinearLayout(DownloadsActivity.this);h.play=Ui.primary(DownloadsActivity.this,"Play offline");actions.addView(h.play,new LinearLayout.LayoutParams(0,Ui.dp(DownloadsActivity.this,48),1));h.more=Ui.icon(DownloadsActivity.this,"options","Download actions");actions.addView(h.more,new LinearLayout.LayoutParams(Ui.dp(DownloadsActivity.this,48),Ui.dp(DownloadsActivity.this,48)));copy.addView(actions);card.addView(copy,new LinearLayout.LayoutParams(0,-2,1));return h;}
 public void onBindViewHolder(Card h,int position){JSONObject record=shown.get(position);String id=record.optString("downloadId"),state=record.optString("state");boolean active=DownloadWorker.isActive(id),complete=state.equals("complete");posters.loadOffline(DownloadsActivity.this,h.art,id);h.title.setText(record.optString("title"));String label=state.equals("downloading")&&!active?"Interrupted":state;h.state.setText((record.optString("versionLabel").isEmpty()?"":record.optString("versionLabel")+" · ")+(complete?"OFFLINE READY · "+bytes(record.optLong("bytes")):active?(record.optInt("percent")==0?"Preparing…":record.optInt("percent")+"% downloaded"):label+" · "+record.optString("message","")));h.progress.setVisibility(active||state.equals("paused")?View.VISIBLE:View.GONE);h.progress.setIndeterminate(active&&record.optInt("percent")==0);h.progress.setProgress(record.optInt("percent"));h.play.setVisibility(complete||active||state.equals("queued")||record.has("contentId")?View.VISIBLE:View.GONE);h.play.setText(complete?"Play offline":active||state.equals("queued")?"Pause":state.equals("failed")?"Retry":"Resume");h.play.setOnClickListener(v->{if(complete)startActivity(new Intent(DownloadsActivity.this,PlayerActivity.class).putExtra("offlineId",id));else if(active||state.equals("queued"))DownloadWorker.control(DownloadsActivity.this,id,"pause");else DownloadWorker.resume(DownloadsActivity.this,id);snapshot="";render();});h.more.setOnClickListener(v->actions(record));}
 public void onViewRecycled(Card h){h.art.setTag(null);h.art.setImageDrawable(null);}}
 protected void onStart(){super.onStart();resumeQueue();handler.post(update);}protected void onStop(){handler.removeCallbacks(update);super.onStop();}protected void onDestroy(){posters.close();super.onDestroy();}protected void onSaveInstanceState(Bundle out){out.putString("filter",filter);super.onSaveInstanceState(out);}
}
